insert into public.exam_questions (id, module, question, options, answer, explanation) values
  (1, 'anatomia', 'Quale parte produce la lamina ungueale?', '["Il letto ungueale","La matrice","L''iponichio","L''eponichio"]'::jsonb, 1, 'La matrice è il tessuto vivo che produce la lamina; la lunula ne è la parte visibile. Per questo la matrice va protetta da pressioni e traumi.'),
  (2, 'anatomia', 'Cosa si rimuove durante la preparazione?', '["L''eponichio, che copre la lunula","La cuticola, pelle morta sulla lamina","L''iponichio sotto il bordo libero","La piega prossimale in eccesso"]'::jsonb, 1, 'Si rimuove solo la cuticola, che è pelle morta aderente alla lamina; eponichio, pieghe e iponichio sono tessuti vivi e non si tagliano.'),
  (3, 'anatomia', 'Dove si trova il punto di stress?', '["Alla base, sotto la cuticola","Dove il bordo libero lascia il letto","Al centro della lunula, sopra la matrice","Sulla punta, al centro del bordo libero"]'::jsonb, 1, 'È la zona in cui il bordo libero lascia il letto e si concentra la leva: lì sopra va costruito l''apex.'),
  (4, 'anatomia', 'Quanto cresce in media un''unghia della mano?', '["Circa 3 mm al mese","Circa 1 cm al mese","Circa 1 mm al mese","Circa 1 mm all''anno"]'::jsonb, 0, 'Circa 0,1 mm al giorno, cioè 3–3,5 mm al mese: è il ritmo che rende necessario il refill dopo 3–4 settimane.'),
  (5, 'anatomia', 'Una cliente ha un''unghia ispessita, giallastra e friabile. Cosa fai?', '["La copri con un gel coprente e la tieni d''occhio","Lavori solo sulle altre dita, con strumenti diversi","Niente servizio: disinfetti e la indirizzi allo specialista","Limi via la parte malata e poi procedi"]'::jsonb, 2, 'Il sospetto di onicomicosi è una controindicazione: lavorare anche sulle altre dita può diffondere l''infezione, e gli strumenti vanno disinfettati.'),
  (6, 'anatomia', 'Cosa indica di solito una macchia verde sotto la ricostruzione?', '["Una muffa innocua dovuta all''umidità","Un''infezione batterica (Pseudomonas)","Un pigmento del colore che è migrato","Una reazione della lamina alla luce della lampada"]'::jsonb, 1, 'Il verde è tipico dello Pseudomonas, un batterio che cresce sotto i sollevamenti umidi: si rimuove il prodotto e si consiglia il medico.'),
  (7, 'anatomia', 'Perché non si deve assottigliare la lamina naturale?', '["Perché diventa troppo lucida","Perché si indebolisce e protegge meno dal calore","Perché cresce più velocemente","Perché il primer non aderisce sulla lamina opaca"]'::jsonb, 1, 'La lamina fa da cuscinetto tra prodotto e letto ungueale: se è sottile si piega, si rompe e lascia passare i picchi di calore.'),
  (8, 'anatomia', 'Quale parte dell''unghia produce la cuticola?', '["La matrice","L''eponichio","L''iponichio","Il letto ungueale"]'::jsonb, 1, 'L''eponichio è pelle viva sotto la piega prossimale e produce la cuticola, che invece è pelle morta: per questo si toglie la cuticola e non l''eponichio.'),
  (9, 'anatomia', 'Quali sono i quattro "sigilli" che proteggono l''unghia?', '["Lunula, matrice, letto ungueale, lamina","Cuticola e piega prossimale, pieghe laterali, iponichio","Bordo libero, apex, punto di stress, lunula","Eponichio, matrice, lunula e letto ungueale"]'::jsonb, 1, 'Sono le barriere contro germi e sostanze esterne: se si tagliano o si forzano, l''unghia diventa vulnerabile alle infezioni.'),
  (10, 'anatomia', 'Una matrice più lunga produce una lamina…', '["Più sottile","Più spessa","Più corta","Più colorata"]'::jsonb, 1, 'Più lunga è la matrice, più strati produce e più spessa è la lamina. Lo spessore naturale non si può cambiare con i trattamenti.'),
  (11, 'anatomia', 'Dopo 3 settimane, quanta ricrescita ti aspetti in media sulle mani?', '["Circa 0,2 mm","Circa 2–2,5 mm","Circa 1 cm","Circa 5 mm"]'::jsonb, 1, 'Con circa 0,8 mm a settimana, in 3 settimane la ricrescita è di circa 2,4 mm: il momento ideale per il refill.'),
  (12, 'anatomia', 'Quale di questi segni di una banda scura sull''unghia richiede il dermatologo con urgenza?', '["Bande sottili e uguali su più dita da anni","Pigmento che si estende sulla pelle intorno all''unghia","Una macchia viola che avanza con la crescita dopo un colpo","Macchioline bianche sparse"]'::jsonb, 1, 'Il pigmento che si allarga sulla piega (segno di Hutchinson) è un segnale d''allarme: non coprire e consiglia subito il dermatologo.'),
  (13, 'anatomia', 'Che cosa sono le linee di Beau (solchi trasversali)?', '["Un''infezione contagiosa che passa da un dito all''altro","Un rallentamento temporaneo della matrice","Il segno di un''allergia agli acrilati in corso","Una forma di micosi che parte dalla base"]'::jsonb, 1, 'Si formano dopo febbre, malattie o traumi e non sono contagiose: si lavora con delicatezza, senza "livellarle" con la lima, che assottiglierebbe la lamina.'),
  (14, 'igiene', 'Quale trattamento elimina anche le spore?', '["La sanificazione","La disinfezione","La sterilizzazione","La detersione"]'::jsonb, 2, 'La disinfezione riduce i germi ma non elimina tutte le spore; solo la sterilizzazione in autoclave elimina ogni forma di vita.'),
  (15, 'igiene', 'Quale autoclave è adatta a strumenti imbustati, cavi e porosi?', '["Classe N","Classe B","Un forno a secco","Una sterilizzatrice a sfere di quarzo"]'::jsonb, 1, 'L''autoclave di classe B (UNI EN 13060) fa il vuoto e fa penetrare il vapore anche in carichi imbustati, cavi e porosi; la classe N no.'),
  (16, 'igiene', 'Quali guanti proteggono dai monomeri?', '["In lattice","In vinile","In nitrile","In cotone"]'::jsonb, 2, 'I monomeri attraversano facilmente lattice e vinile: per lavorare con acrilati si usa il nitrile, cambiato spesso.'),
  (17, 'igiene', 'Quale sostanza è vietata nei cosmetici nell''UE dal 1° settembre 2025?', '["L''HEMA","Il TPO","L''acetone","L''EMA"]'::jsonb, 1, 'Il Reg. UE 2025/877 vieta TPO e DMTA, anche per uso professionale e per le scorte già acquistate; l''HEMA resta ammesso, ma solo per uso professionale.'),
  (18, 'igiene', 'Come è regolato l''HEMA nei prodotti per unghie?', '["È vietato del tutto dal 2025","È libero anche per uso domestico","Solo uso professionale, con avvertenze","È ammesso solo nei top coat, senza avvertenze"]'::jsonb, 2, 'Il Reg. UE 2020/1682 lo limita all''uso professionale, con l''avvertenza "Può provocare una reazione allergica".'),
  (19, 'igiene', 'Quando è concreto il rischio di allergia agli acrilati?', '["Quando il prodotto polimerizzato è sulla lamina","Quando il prodotto non polimerizzato tocca la pelle","Solo con la lampada LED","Solo con i colori scuri"]'::jsonb, 1, 'Il prodotto ben polimerizzato è stabile; è il contatto ripetuto della pelle con prodotto non polimerizzato a causare la sensibilizzazione.'),
  (20, 'igiene', 'In Italia, cosa serve per fare ricostruzione unghie in proprio?', '["Solo un attestato di un corso privato","La qualifica di estetista e la SCIA","Nessun requisito","Solo la partita IVA"]'::jsonb, 1, 'La ricostruzione rientra nell''attività di estetista (L. 1/1990): serve la qualifica e l''apertura si comunica con la SCIA.'),
  (21, 'igiene', 'Che cosa significa "tempo di contatto" di un disinfettante?', '["Quanto dura il flacone dopo l''apertura","Quanto la superficie deve restare bagnata","Il tempo per far asciugare le mani dopo la frizione","La durata del ciclo completo in autoclave"]'::jsonb, 1, 'È il tempo in cui la superficie deve restare bagnata perché il prodotto agisca: se si asciuga o la sciacqui prima, il disinfettante non fa effetto.'),
  (22, 'igiene', 'Cosa fai con una lima in carta usata su una cliente?', '["La disinfetti con alcol e la riusi","La metti in autoclave","La butti o la regali alla cliente","La lavi con acqua e sapone e la riusi"]'::jsonb, 2, 'È porosa e trattiene polvere e germi: non si può disinfettare davvero, quindi è monouso.'),
  (23, 'igiene', 'A fine ciclo trovi una busta di sterilizzazione umida. Cosa fai?', '["La usi lo stesso, se l''indicatore è virato","La asciughi con una salvietta pulita e la riponi","Non è sterile: reimbusti e risterilizzi","La metti nel box UV per completare la sterilizzazione"]'::jsonb, 2, 'Una busta umida significa sterilizzazione non riuscita: asciughi lo strumento, lo metti in una busta nuova e ripeti il ciclo.'),
  (24, 'igiene', 'Qual è la protezione più efficace contro la polvere di limatura?', '["La mascherina chirurgica, cambiata spesso","L''aspirazione vicino alle mani","Aprire la finestra a fine giornata","Spolverare il tavolo con un pennello dopo ogni cliente"]'::jsonb, 1, 'La polvere va catturata alla fonte, con tavolo aspirante o cappa, prima che arrivi alle vie respiratorie; i DPI, come la FFP2, sono l''ultima barriera.'),
  (25, 'igiene', 'Dove si trova soprattutto la DMTA, vietata dal 1° settembre 2025?', '["Negli smalti tradizionali, come solvente","Nei liquidi per acrilico e negli attivatori dip","Nell''acetone puro per la rimozione","Nell''olio per cuticole, come conservante"]'::jsonb, 1, 'La N,N-dimetil-p-toluidina accelera l''indurimento dei sistemi senza lampada: controlla l''INCI di monomeri e attivatori.'),
  (26, 'igiene', 'Ti pungi con una tronchesina appena usata su una cliente. Cosa fai per prima cosa?', '["Metti un cerotto, finisci il servizio e poi disinfetti","Fai sanguinare, lavi 10 minuti, disinfetti e vai dal medico","Immergi il dito nell''alcol e continui con un guanto nuovo","Disinfetti la tronchesina e ci pensi a fine giornata"]'::jsonb, 1, 'È la procedura delle linee guida per l''esposizione a sangue: favorire il sanguinamento, lavare 10 minuti con acqua e antisettico, disinfettare e farsi valutare subito da un medico.'),
  (27, 'sistemi', 'Che cosa caratterizza il gel monofasico?', '["Non ha bisogno della lampada","Fa da base, costruttore e sigillante","Si usa solo per il french","È un tipo di acrilico"]'::jsonb, 1, 'Un solo prodotto copre tutte e tre le fasi: aderenza, struttura e finitura. Va comunque polimerizzato in lampada.'),
  (28, 'sistemi', 'Come indurisce l''acrilico?', '["In lampada UV, come il gel","Per reazione tra liquido e polvere","A contatto con l''acetone del cleaner","Solo spruzzando l''attivatore a fine lavoro"]'::jsonb, 1, 'Il perossido di benzoile nella polvere e l''accelerante nel liquido avviano la reazione a temperatura ambiente, senza lampada.'),
  (29, 'sistemi', 'Cosa succede con una perla di acrilico troppo bagnata?', '["Diventa la più resistente e flessibile","Cola nei solchi e verso la pelle","Diventa granulosa, opaca e porosa","Indurisce troppo in fretta sul pennello"]'::jsonb, 1, 'Troppo liquido significa colature verso cuticola e solchi, ritiro e monomero libero sulla pelle, quindi più rischio di allergia.'),
  (30, 'sistemi', 'Come si lavora il polygel?', '["Con monomero liquido, senza lampada","Con slip solution e pennello, poi in lampada","Con acqua","Con colla per tip"]'::jsonb, 1, 'Il polygel si modella con il pennello inumidito di slip solution e indurisce solo in lampada.'),
  (31, 'sistemi', 'Cosa fa il semipermanente?', '["Allunga l''unghia come un builder","Dà colore, ma non struttura","Si toglie solo con la fresa","Indurisce all''aria senza lampada"]'::jsonb, 1, 'È colore su unghia naturale che dura in genere 2–3 settimane, polimerizzato in lampada: non ha la struttura per allungare né per reggere una lunghezza.'),
  (32, 'sistemi', 'Per scegliere la lampada cosa conta soprattutto?', '["Il numero di watt dichiarato sulla scatola","Il colore e la forma della scocca","Le lunghezze d''onda adatte al gel","La marca più diffusa nei saloni"]'::jsonb, 2, 'Il gel indurisce solo se riceve le lunghezze d''onda che i suoi fotoiniziatori assorbono: usa la lampada indicata dal produttore del sistema.'),
  (33, 'sistemi', 'Qual è il picco di emissione tipico di una lampada LED per unghie?', '["Circa 250 nm","Circa 500 nm","Circa 365–405 nm","Circa 700 nm"]'::jsonb, 2, 'Le lampade LED per unghie emettono in genere picchi a 365 e/o 405 nm, dove assorbono i fotoiniziatori dei gel.'),
  (34, 'sistemi', 'Perché un soft gel si toglie con l''acetone e un hard gel no?', '["Perché il soft gel non va in lampada","Perché la sua rete di polimero è più aperta","Perché l''hard gel contiene già un solvente","Perché il soft gel è in realtà un tipo di acrilico"]'::jsonb, 1, 'Nella rete più aperta del soft gel l''acetone entra e la gonfia; l''hard gel, molto reticolato, non si scioglie e si toglie limando.'),
  (35, 'sistemi', 'Lo strato appiccicoso che resta sul gel dopo la lampada…', '["Indica che la lampada è guasta o vecchia","Dipende dall''ossigeno e si toglie col cleaner","Va lasciato anche sopra il top finale","Si toglie con acqua e sapone a fine lavoro"]'::jsonb, 1, 'È lo strato di dispersione: tra uno strato e l''altro aiuta l''aggancio, a fine lavoro si toglie con cleaner, una salvietta per dito, senza portarlo sulla pelle.'),
  (36, 'sistemi', 'Nella polvere dell''acrilico, cosa fa partire la reazione?', '["L''acetone contenuto nella polvere","Il perossido di benzoile","Il pigmento rosa o bianco","La luce della lampada da tavolo"]'::jsonb, 1, 'Il perossido di benzoile (BPO) è l''iniziatore: attivato dall''accelerante del liquido, avvia la polimerizzazione a temperatura ambiente.'),
  (37, 'sistemi', 'Perché non conviene usare il liquido di una marca con la polvere di un''altra?', '["Perché cambia il colore finale","Perché iniziatore e accelerante sono calibrati","Perché è vietato dal regolamento UE","Perché la polvere si scioglie nel liquido sbagliato"]'::jsonb, 1, 'Con una coppia non calibrata l''acrilico può restare sottopolimerizzato o fragile; più monomero non reagito significa anche più rischio di allergia.'),
  (38, 'sistemi', 'Una lampada da 36 W polimerizza sicuramente meglio di una da 9 W?', '["Sì, più watt vuol dire sempre più luce utile","No: contano lunghezze d''onda e intensità","Sì, se è una lampada UV e non LED","Sì, ma solo con i colori chiari e i top"]'::jsonb, 1, 'I watt misurano il consumo elettrico, non la luce utile: conta che la lampada emetta le lunghezze d''onda del gel con intensità sufficiente sull''unghia.'),
  (39, 'sistemi', 'Nel sistema dip, qual è il modo igienico di applicare la polvere?', '["Immergere il dito nel barattolo comune","Versare la polvere su un contenitore monouso","Immergere il dito dopo averlo disinfettato","Recuperare la polvere caduta per la cliente dopo"]'::jsonb, 1, 'La polvere non si può disinfettare: si versa con un cucchiaino pulito su un contenitore monouso e l''avanzo si butta, invece di contaminare il barattolo comune.'),
  (40, 'attrezzatura', 'Quale grana è la più abrasiva?', '["80","180","240","Buffer"]'::jsonb, 0, 'Più basso è il numero, più grossi sono i granuli e più la lima toglie materiale: 80 è la più aggressiva.'),
  (41, 'attrezzatura', 'Quale grana usi sull''unghia naturale?', '["80–100","100/180","180–240","Punta in carburo"]'::jsonb, 2, 'Con 180–240 togli solo la lucidità senza assottigliare la lamina; le grane più grosse servono sul prodotto artificiale.'),
  (42, 'attrezzatura', 'Dove si usano le punte in carburo?', '["Sulla cuticola","Solo sul prodotto artificiale","Sull''unghia naturale","Per lucidare la lamina"]'::jsonb, 1, 'Il carburo taglia molto: si usa solo sul prodotto. Sulla lamina naturale e in zona cuticolare si usano punte diamantate fini.'),
  (43, 'attrezzatura', 'Quale velocità indicativa usi in zona cuticolare?', '["Circa 2.000–10.000 RPM","Circa 20.000–25.000 RPM","Circa 30.000 RPM","La velocità massima"]'::jsonb, 0, 'Più sei vicina alla pelle, più vai piano: velocità basse e pressione leggera riducono calore e rischio di ferite.'),
  (44, 'attrezzatura', 'Perché la punta della fresa deve restare sempre in movimento?', '["Per lucidare meglio","Per evitare calore da attrito e solchi","Per consumare meno la punta","Per aumentare i giri del motore"]'::jsonb, 1, 'Una punta ferma in un punto scalda per attrito e scava un solco nella superficie.'),
  (45, 'attrezzatura', 'Cosa fai con una lima in vetro usata su pelle integra, dopo la cliente?', '["La butti","La pulisci e la disinfetti","La riusi subito sulla cliente successiva","La passi solo con il buffer"]'::jsonb, 1, 'Il vetro non è poroso, quindi si può pulire e disinfettare; le lime in carta invece sono monouso.'),
  (46, 'attrezzatura', 'Che cosa sono gli "anelli di fuoco"?', '["Un effetto di nail art con il chrome","Solchi circolari da punta inclinata","Un tipo di lampada a LED circolare","Il segno bianco lasciato dal primer acido"]'::jsonb, 1, 'Sono solchi circolari scavati da una punta della fresa tenuta inclinata: si evitano tenendola parallela alla superficie, leggera e sempre in movimento.'),
  (47, 'attrezzatura', 'Qual è il diametro standard del gambo delle punte professionali per fresa?', '["1/8 di pollice (3,17 mm)","3/32 di pollice (2,35 mm)","5 mm","4 mm"]'::jsonb, 1, 'Le punte professionali hanno gambo da 2,35 mm; il gambo da 1/8 di pollice (3,17 mm) è quello degli attrezzi da bricolage, che non vanno usati sulle clienti.'),
  (48, 'attrezzatura', 'Come si pulisce un pennello da acrilico in setole naturali?', '["In acetone puro, ogni sera","Nel monomero, poi asciugato e rimodellato","Con acqua tiepida e sapone neutro","Con il cleaner per gel e una salvietta"]'::jsonb, 1, 'Acetone e acqua seccano e rovinano le setole; il monomero scioglie i residui e le mantiene morbide.'),
  (49, 'attrezzatura', 'Cosa fai con le bande abrasive per fresa (carta su mandrino) dopo la cliente?', '["Le sterilizzi in autoclave","Le butti: sono monouso","Le lavi con acqua e sapone","Le disinfetti con alcol"]'::jsonb, 1, 'Sono porose come le lime in carta: non si possono disinfettare davvero e si buttano dopo ogni cliente.'),
  (50, 'preparazione', 'Qual è la prima causa di sollevamento?', '["Una lampada poco potente","Una preparazione non accurata","Il colore scelto dalla cliente","La forma limata a punta"]'::jsonb, 1, 'Pellicine di cuticola, polvere, sebo e umidità rimasti sulla lamina impediscono l''adesione: la preparazione è la base di tutto.'),
  (51, 'preparazione', 'A cosa serve l''opacizzazione dell''unghia naturale?', '["Ad assottigliarla","A togliere la lucidità","Ad accorciarla","A sbiancarla"]'::jsonb, 1, 'Si toglie solo la lucidità superficiale per aiutare l''adesione, mai spessore: una lamina assottigliata si indebolisce.'),
  (52, 'preparazione', 'Qual è l''ordine corretto?', '["Primer, poi disidratante","Disidratante, poi primer","Solo primer, senza disidratante","Base, poi primer"]'::jsonb, 1, 'Il disidratante toglie sebo e umidità; il primer lavora poi su una lamina pulita e asciutta.'),
  (53, 'preparazione', 'Per cosa è indicato soprattutto il primer acido?', '["Il semipermanente su unghie sane e sottili","Acrilico e unghie grasse o che si sollevano","Il top coat, per farlo aderire meglio","La rimozione, per ammorbidire il prodotto"]'::jsonb, 1, 'Si usa con l''acrilico tradizionale e su unghie molto grasse o con sollevamenti ripetuti; è più aggressivo, quindi in quantità minima e solo sulla lamina.'),
  (54, 'preparazione', 'Cosa fai dopo aver passato il disidratante?', '["Tocchi la lamina per controllare","Non tocchi più la lamina con le dita","Fai lavare le mani alla cliente","Applichi olio per cuticole"]'::jsonb, 1, 'Il sebo delle dita, tue o della cliente, ritorna sulla lamina e riduce l''adesione.'),
  (55, 'preparazione', 'Che cos''è il vero pterigio?', '["La pellicina morta da togliere sempre","Pelle saldata alla lamina: non si tocca","Il bordo libero che sporge dal letto","Un tipo di primer per unghie difficili"]'::jsonb, 1, 'Non è la cuticola: è una specie di cicatrice che unisce pelle e lamina. Non si taglia e non si spinge, si indirizza al medico.'),
  (56, 'preparazione', 'Con quale angolo tieni lo spingicuticole per arretrare l''eponichio?', '["Dritto, a 90° sulla lamina","Quasi parallelo, circa 30–45°","Capovolto, con la parte curva sulla lamina","A 60–75°, per fare più presa"]'::jsonb, 1, 'Uno strumento tenuto dritto graffia la lamina e preme sulla matrice; quasi parallelo scorre senza danni.'),
  (57, 'preparazione', 'Quale grana NON si usa mai sulla lamina naturale?', '["240","180","100","Buffer fine"]'::jsonb, 2, 'Le grane 80–100 assottigliano la lamina e servono solo sul prodotto artificiale; sull''unghia naturale si usa 180–240.'),
  (58, 'preparazione', 'Come deve essere il pennello del primer prima di applicarlo?', '["Ben carico","Quasi asciutto","Bagnato di acetone","Inumidito di olio"]'::jsonb, 1, 'Il primer in eccesso riduce l''adesione e scivola verso pelle e solchi: si scarica il pennello e si procede a piccoli tocchi.'),
  (59, 'preparazione', 'Dove si applica il primer senza acido?', '["Su lamina e tip, per uniformare","Solo sulla lamina, ad almeno 1 mm dalla pelle","Sulla pelle intorno, per proteggerla","Sopra la base, prima del colore"]'::jsonb, 1, 'Il primer serve solo dove c''è cheratina: sul tip non serve, sulla pelle è un acrilato a rischio di sensibilizzazione.'),
  (60, 'preparazione', 'Quando il primer acido è pronto per il prodotto?', '["Quando è ancora bagnato e lucido","Quando è asciutto e appare bianco gessoso","Dopo circa 20 minuti","Dopo la polimerizzazione in lampada"]'::jsonb, 1, 'Si lavora sul primer acido asciutto, di aspetto bianco gessoso: se è ancora bagnato, il prodotto aderisce male e può ritirarsi.'),
  (61, 'tip', 'Come scegli la misura del tip?', '["Il più piccolo possibile, così non tocca la pelle","Deve coprire da solco a solco","Sempre la stessa misura su tutte le dita","Quello che copre anche le pieghe laterali"]'::jsonb, 1, 'Il tip deve coprire da solco a solco senza toccare la pelle; se sei tra due misure scegli la più grande e lima i lati.'),
  (62, 'tip', 'Con quale angolo si appoggia il tip?', '["90°","Circa 45°, poi lo abbassi lentamente","0°, piatto subito","Circa 10°, quasi piatto, premendo forte"]'::jsonb, 1, 'Abbassando il tip lentamente dalla base verso la punta l''aria esce e non restano bolle sotto la colla.'),
  (63, 'tip', 'Cosa fai durante il blending del tip?', '["Limi anche l''unghia naturale","Fondi solo la linea di contatto del tip","Usi grana 80 sulla lamina","Usi acetone sulla linea di contatto"]'::jsonb, 1, 'Si lima solo la plastica dell''incavo fino a rendere invisibile il gradino; la lamina naturale non si tocca.'),
  (64, 'tip', 'Che cosa caratterizza i tip "a contatto"?', '["Hanno un incavo lungo da fondere","Non hanno incavo e non vanno fusi","Si applicano senza colla","Si usano solo per i piedi"]'::jsonb, 1, 'Si incollano solo sul bordo libero: senza incavo non c''è alcuna zona da fondere.'),
  (65, 'tip', 'Quanto può coprire al massimo l''incavo del tip?', '["Tutta la lamina, fino alla cuticola","Circa metà della lamina","Solo 1 mm","Due terzi della lamina"]'::jsonb, 1, 'Un incavo troppo lungo copre troppa lamina e si solleva: se supera metà unghia si accorcia prima di incollare.'),
  (66, 'tip', 'Per quanto tempo tieni premuto il tip dopo averlo abbassato?', '["Non serve tenerlo","Circa 5–10 secondi, fermo","Circa 2 minuti","Finché la cliente sente caldo"]'::jsonb, 1, 'Muovere il tip mentre la colla indurisce indebolisce il legame e lascia spazio a bolle d''aria.'),
  (67, 'tip', 'Quando si taglia il tip alla lunghezza voluta?', '["Prima di incollarlo","Quando la colla è indurita","Mentre la colla è ancora liquida","Dopo il top"]'::jsonb, 1, 'Tagliando a colla fresca il tip si sposta e il legame si rompe: si taglia dopo l''indurimento.'),
  (68, 'tip', 'Come tieni la lima durante la fusione del tip?', '["Di taglio, premendo sulla linea","Piatta, solo sulla plastica","Ferma su un punto, finché sparisce","Inclinata verso la cuticola, a 45°"]'::jsonb, 1, 'Una lima ferma o di taglio crea solchi; se tocca la lamina la assottiglia. Piatta, sulla plastica e sempre in movimento fonde solo il tip.'),
  (69, 'tip', 'Dove applichi il primer in una ricostruzione su tip?', '["Su tutto il tip","Solo sulla lamina naturale","Sulla pelle intorno","Solo sulla linea di contatto"]'::jsonb, 1, 'Il primer aiuta l''adesione sulla cheratina; sul tip non serve e può rovinare la plastica.'),
  (70, 'tip', 'Che cosa indica una macchia chiara sotto l''incavo dopo l''incollaggio?', '["Una bolla d''aria: va riapplicato","Che la colla ha fatto bene presa","Una micosi sotto la lamina","Il punto di stress dell''unghia"]'::jsonb, 0, 'È una bolla d''aria, cioè un punto senza adesione: diventa un sollevamento e trattiene umidità, quindi il tip va rimosso e riapplicato.'),
  (71, 'cartina', 'Dove va costruito l''apex?', '["Vicino alla cuticola","Sopra il punto di stress","Sulla punta","Al centro del bordo libero"]'::jsonb, 1, 'L''apex è la parte più spessa, in zona 2: deve stare sopra il punto di stress, dove la leva della lunghezza è maggiore.'),
  (72, 'cartina', 'Quanto margine lasci dalla pelle in zona cuticolare?', '["Nessuno","Circa 1 mm","Circa 5 mm","Circa 1 cm"]'::jsonb, 1, 'Circa 1 mm (le fonti indicano 0,5–1,5 mm): il prodotto non deve mai toccare la pelle, per evitare sollevamenti e allergie.'),
  (73, 'cartina', 'Cosa succede se la cartina lascia uno spazio sotto il bordo libero?', '["Niente, se il prodotto è denso","Il prodotto cola sotto","L''unghia diventa più robusta in punta","Il prodotto polimerizza più in fretta"]'::jsonb, 1, 'Il prodotto colato sotto il bordo crea uno scalino debole che fa leva e porta a sollevamenti: la cartina va sempre a filo del bordo libero.'),
  (74, 'cartina', 'Cosa succede a una ricostruzione piatta, senza apex?', '["È più naturale e anche più resistente","Si crepa nella zona di stress","Non si solleva mai alla cuticola","Dura di più tra un refill e l''altro"]'::jsonb, 1, 'Senza spessore sopra il punto di stress la struttura non regge la leva della lunghezza e si crepa lì o sui lati.'),
  (75, 'cartina', 'Quando si pizzica il gel per la curva a C?', '["Prima di stenderlo sulla cartina","Dopo un flash cure di pochi secondi","Dopo il top, a lavoro finito","Dopo la polimerizzazione completa"]'::jsonb, 1, 'Il gel va pizzicato dopo pochi secondi di lampada, poi si completa la polimerizzazione; l''acrilico invece quando ha perso la lucidità ma è ancora morbido.'),
  (76, 'cartina', 'Come deve essere la zona 3, in zona cuticolare?', '["La più spessa","Sottilissima, \"a filo\"","Bianca","Spessa quanto il bordo libero"]'::jsonb, 1, 'In zona 3 il prodotto si fonde con l''unghia: così non si vede il gradino quando ricresce. La struttura sta in zona 2.'),
  (77, 'cartina', 'Come appare di profilo una cartina posizionata correttamente?', '["Inclinata verso il basso, per non pungere","In linea retta con la lamina","Inclinata verso l''alto, per la curva","Staccata di poco dal bordo libero"]'::jsonb, 1, 'Se scende l''allungamento "cade", se sale si ottiene una punta all''insù (ski-jump).'),
  (78, 'cartina', 'Come si fissano le alette della cartina?', '["Avvolgendo tutta la nocca","Sotto il polpastrello e sui lati","Sopra l''unghia, incrociate","Con la colla per tip, sulla pelle"]'::jsonb, 1, 'Le alette chiuse sotto il polpastrello tengono la cartina ferma; avvolte sulla nocca si staccano quando il dito si piega.'),
  (79, 'cartina', 'Una cliente con iponichio lungo sente dolore con la cartina. Cosa fai?', '["Spingi di più per far aderire la cartina","Ritagli un incavo più profondo nel punto di contatto","Continui comunque","Applichi un primer acido"]'::jsonb, 1, 'La cartina deve toccare il bordo libero senza premere sulla pelle viva: il dolore è un segnale di pressione sull''iponichio.'),
  (80, 'cartina', 'Quanto è spesso, indicativamente, il bordo libero finito?', '["Come un foglio di carta da stampante","Circa 0,8–1 mm","Circa 2–3 mm, per resistere","Come l''apex, per uniformità"]'::jsonb, 1, 'È circa lo spessore di una carta di credito (0,76 mm) o poco più: più spesso il bordo si nota e si impiglia, più sottile si scheggia.'),
  (81, 'cartina', 'Una perla di acrilico media ha un rapporto liquido/polvere di circa…', '["1 : 1","1,5 : 1","2 : 1","1 : 2"]'::jsonb, 1, 'Circa 1 : 1 è asciutta e 2 : 1 bagnata; 1,5 : 1 è un riferimento per molti sistemi EMA, ma il valore esatto dipende dal produttore.'),
  (82, 'cartina', 'Per un risultato equilibrato, quanto dovrebbe essere lungo al massimo il bordo libero?', '["Il doppio del letto ungueale","Circa metà del letto ungueale","Non oltre 1 mm dal polpastrello","Quanto tutto il letto ungueale"]'::jsonb, 1, 'Più lunghezza significa più leva sul punto di stress: per l''uso quotidiano il bordo libero resta entro circa metà del letto.'),
  (83, 'limatura', 'Quale forma è considerata tra le più resistenti?', '["Stiletto","Squoval","Lipstick","Ballerina"]'::jsonb, 1, 'La squoval è una quadrata con gli angoli smussati: non ha punte strette né angoli che si impigliano e si scheggiano.'),
  (84, 'limatura', 'Tra queste forme, quale slancia di più il dito?', '["Quadrata","Mandorla","Tonda","Squoval"]'::jsonb, 1, 'I lati convergenti della mandorla allungano visivamente il dito; la quadrata invece lo accorcia e lo allarga.'),
  (85, 'limatura', 'Come si limano i lati?', '["Con la lima parallela al solco laterale","Entrando nel solco per pulirlo","Con la grana 80","In diagonale verso il centro"]'::jsonb, 0, 'Una lima piatta e parallela al solco dà lati dritti senza entrare nel solco, dove feriresti la pelle e indeboliresti il lato.'),
  (86, 'limatura', 'Qual è il movimento corretto della lima?', '["Avanti e indietro veloce","In una sola direzione","Circolare, premendo","Avanti e indietro, ma lento"]'::jsonb, 1, 'Il movimento "a sega" scalda e sfibra il bordo; in una sola direzione il taglio resta pulito.'),
  (87, 'limatura', 'Da quali punti di vista controlli la ricostruzione?', '["Solo dall''alto, con buona luce","Alto, profilo, fronte e sotto","Solo di profilo, per l''apex","Dall''alto e da sotto il bordo"]'::jsonb, 1, 'Ogni vista mostra qualcosa: dall''alto simmetria e forma, di profilo l''apex, dal davanti la curva a C, da sotto la pulizia del bordo.'),
  (88, 'limatura', 'In quale ordine si lima una ricostruzione?', '["Superficie, punta, lunghezza, lati","Lunghezza, lati, punta, superficie","Punta, lati, superficie, lunghezza","Lati, superficie, lunghezza, punta"]'::jsonb, 1, 'La forma si decide sulla lunghezza finale, quindi prima si accorcia; poi lati e punta, la superficie alla fine e per ultimo il controllo sotto il bordo.'),
  (89, 'limatura', 'Da quale forma conviene partire per ottenere quasi tutte le altre?', '["Dalla stiletto","Dalla quadrata","Dalla tonda","Dalla lipstick"]'::jsonb, 1, 'Da una base quadrata con lati paralleli, togliendo gli angoli in modo diverso, si arriva alle altre forme mantenendo l''asse e la simmetria.'),
  (90, 'limatura', 'Come tieni il dito della cliente durante la limatura?', '["Con un tuo dito appoggiato sull''unghia","Ai lati, senza toccare la superficie","Per la punta dell''unghia, stringendo","Lasciandolo libero sul cuscinetto"]'::jsonb, 1, 'Lo tieni ai lati della prima falange: toccare la superficie lascia sebo e ti impedisce di vedere il lavoro.'),
  (91, 'limatura', 'Come si riconosce la ballerina (coffin)?', '["I lati si allargano verso la punta","I lati si restringono e la punta è dritta","La punta è tonda","È una quadrata corta con angoli smussati"]'::jsonb, 1, 'Si restringe come una stiletto, ma ci si ferma prima e la punta si taglia dritta.'),
  (92, 'limatura', 'Perché si segna un puntino al centro della punta prima di limare?', '["Per decorare","Come riferimento per la simmetria","Per sapere dove mettere il primer","Per segnare dove finisce l''apex"]'::jsonb, 1, 'Il puntino indica dove deve cadere la punta, sull''asse del dito: contando le passate sui due lati la forma resta centrata.'),
  (93, 'limatura', 'Il top può correggere piccoli difetti di limatura?', '["Sì, li nasconde","No, li mette in risalto","Solo quelli sui lati","Sì, con due strati"]'::jsonb, 1, 'Il top è sottile e lucido e riflette la luce su ogni irregolarità: i difetti si correggono con la lima prima del top.'),
  (94, 'decorazioni', 'Com''è una buona smile line?', '["Leggermente asimmetrica, per sembrare naturale","Simmetrica, netta e con la stessa profondità sui lati","Piatta e dritta","Sfumata verso il letto"]'::jsonb, 1, 'Simmetria e nettezza sono i criteri principali, e la smile line deve essere uguale su tutte le dita.'),
  (95, 'decorazioni', 'Che effetto ha una smile line troppo piatta?', '["Allunga visivamente il letto ungueale","Fa sembrare l''unghia più larga e corta","Nessun effetto visibile","Rende il bianco più coprente"]'::jsonb, 1, 'La profondità della curva cambia la percezione: una smile piatta allarga e accorcia, una troppo profonda sembra innaturale.'),
  (97, 'decorazioni', 'Perché il gel bianco si stende in strati sottili?', '["Per risparmiare prodotto e tempo","Perché il pigmento scherma la luce","Perché il bianco non polimerizza mai del tutto","Per renderlo semitrasparente come un jelly"]'::jsonb, 1, 'È l''effetto ombrello dei pigmenti: due strati sottili ben polimerizzati sono più sicuri di uno spesso, che resta sottopolimerizzato.'),
  (98, 'decorazioni', 'Nel reverse french, dove e come si disegna l''arco di colore?', '["Sul bordo libero, da un lato all''altro","Alla base, dal centro, a 1 mm dalla pelle","Alla base, toccando la cuticola per coprirla","Con lo stamping, mai a mano libera"]'::jsonb, 1, 'Partire dal centro aiuta a fare un arco regolare; il margine dalla pelle evita sollevamenti e contatto con il prodotto.'),
  (99, 'decorazioni', 'Che cos''è il baby boomer?', '["Un french con linea netta","Una sfumatura dal nude al bianco","Un tipo di gel","Una forma dell''unghia"]'::jsonb, 1, 'È un french sfumato: il bianco della punta si fonde gradualmente con il nude, senza una linea netta.'),
  (100, 'decorazioni', 'Nel baby boomer, come si ottiene soprattutto la sfumatura?', '["Limando forte la zona di passaggio","Con il pennello, a strati sottili","Con un solo strato spesso di bianco","Con il top coat passato più volte"]'::jsonb, 1, 'La lima assottiglia la zona sfumata e crea macchie; la sfumatura si costruisce con il pennello, strato dopo strato.'),
  (101, 'decorazioni', 'In cosa consiste l''incapsulato?', '["Chiudere decorazioni nel prodotto","Applicare glitter sopra il top finito","Usare solo colori pieni, senza effetti","Dipingere piccoli punti con il dotter"]'::jsonb, 0, 'Le decorazioni restano chiuse tra due strati trasparenti, con l''apex costruito sopra: non si consumano e non si impigliano.'),
  (102, 'decorazioni', 'Cosa serve per lo stamping?', '["Una piastra incisa e un tampone","Una fresa con punta fine","Un attivatore spray","Solo pennelli fini"]'::jsonb, 0, 'Lo smalto steso sulla piastra resta nelle incisioni e il tampone trasferisce il disegno sull''unghia.'),
  (103, 'decorazioni', 'Nello stamping, come si passa il raschietto?', '["In verticale, premendo forte","Inclinato a circa 45°","Dopo aver usato il tampone","Solo a smalto secco sulla piastra"]'::jsonb, 1, 'Inclinato a circa 45° il raschietto toglie l''eccesso e lascia lo smalto solo nelle incisioni; poi si rotola subito il tampone.'),
  (104, 'manutenzione', 'Ogni quanto si consiglia il refill di una ricostruzione?', '["Ogni settimana","Ogni 3–4 settimane","Ogni 2–3 mesi","Solo quando si rompe"]'::jsonb, 1, 'Dopo 3–4 settimane l''apex si è spostato in avanti con la ricrescita; il semipermanente invece si rifà in genere ogni 2–3 settimane.'),
  (106, 'manutenzione', 'Cosa fai, durante il refill, con le parti sollevate?', '["Le copri con prodotto nuovo","Le elimini completamente","Le incolli con colla per tip","Le lasci, se sono piccole"]'::jsonb, 1, 'Sotto un sollevamento possono esserci umidità e batteri: coprirlo chiude il problema dentro e il prodotto nuovo non aderisce.'),
  (107, 'manutenzione', 'Come si elimina un sollevamento durante il refill?', '["Si taglia con la tronchesina","Si lima fino al prodotto ben aderente","Si stacca tirandolo con le pinzette","Si ammorbidisce con acetone e si raschia"]'::jsonb, 1, 'Tagliare o strappare porta via strati di lamina e crea nuovi sollevamenti; limando ti fermi dove il prodotto è ancora aderente.'),
  (108, 'manutenzione', 'Durante il rebalance, di quanto si assottiglia indicativamente il vecchio prodotto?', '["Per niente: si lavora sopra","Del 30–50%","Fino all''unghia naturale","Solo sul bordo libero"]'::jsonb, 1, 'Indicativamente del 30–50%, in base alla ricrescita: così puoi ricostruire l''apex nel punto giusto senza rendere l''unghia sempre più spessa.'),
  (109, 'manutenzione', 'Una cliente ha una crepa nel prodotto: cosa le consigli fino all''appuntamento?', '["Di incollarla con la colla per tip","Di coprirla con un cerotto","Di non incollarla né coprirla e prenotare","Di staccare il prodotto da sola"]'::jsonb, 2, 'Colla e cerotto chiudono umidità e batteri sotto il prodotto e strapparlo porta via la lamina: al massimo si lima la parte che si aggancia, in attesa della riparazione.'),
  (110, 'manutenzione', 'Quanto tempo serve in genere per il soak-off del semipermanente?', '["Circa 1 minuto","Circa 10–15 minuti","Circa 45 minuti","Circa 2 ore"]'::jsonb, 1, 'Il semipermanente si ammorbidisce in circa 10–15 minuti; soft gel spessi arrivano a circa 30, l''acrilico richiede in genere 20–30 minuti.'),
  (111, 'manutenzione', 'Quale tempo in acetone è più realistico per un acrilico già assottigliato?', '["1–2 minuti","20–30 minuti","2 ore","Non si scioglie in acetone"]'::jsonb, 1, 'L''acrilico richiede più tempo del semipermanente (10–15 min); è l''hard gel che non si scioglie e si toglie limando.'),
  (112, 'manutenzione', 'Come si rimuove l''hard gel?', '["Con l''acetone, come il soft gel","Limando, lasciando un velo","Strappandolo dopo averlo scaldato","Con acqua calda e olio"]'::jsonb, 1, 'La sua rete di polimero è molto fitta e non si scioglie in acetone; il velo lasciato sulla lamina evita di assottigliarla.'),
  (113, 'manutenzione', 'Subito dopo un soak-off la lamina appare biancastra. Che cos''è di solito?', '["Un danno permanente della lamina","Disidratazione temporanea","Una micosi superficiale","Prodotto rimasto sulla lamina"]'::jsonb, 1, 'L''acetone disidrata la superficie e il bianco sparisce in alcune ore; i danni veri vengono dal raschiare o dal fare leva.'),
  (114, 'manutenzione', 'Cosa fai subito dopo la rimozione?', '["Gratti la lamina per togliere i residui","Applichi olio per cuticole","Applichi subito un nuovo gel senza preparare","Limi la lamina con grana 80"]'::jsonb, 1, 'L''olio nutre pelle e lamina disidratate dall''acetone; residui e preparazione si gestiscono con delicatezza, mai raschiando.'),
  (115, 'problemi', 'Quale di queste NON è una causa di sollevamento?', '["Cuticola rimasta sulla lamina","Prodotto a contatto con la pelle","Bordo libero sigillato","Refill fatto in ritardo"]'::jsonb, 2, 'Sigillare il bordo libero previene il sollevamento in punta; le altre tre sono cause tipiche.'),
  (116, 'problemi', 'Un sollevamento al centro dell''unghia ("a tasca") fa pensare soprattutto a…', '["Bordo libero non sigillato","Adesione scarsa o un trauma","Prodotto nei solchi laterali","Prodotto sulla cuticola"]'::jsonb, 1, 'Il centro è lontano dalla pelle: le cause tipiche sono adesione insufficiente, rapporto liquido/polvere sbagliato e colpi.'),
  (118, 'problemi', 'Il sollevamento compare su tutte le dita di una cliente dopo pochi giorni. Cosa controlli per primo?', '["Le abitudini della cliente","La tua preparazione e applicazione","Il colore scelto","La forma limata"]'::jsonb, 1, 'Tutte le dita e subito indicano un problema di protocollo, prodotto o lampada; abitudini e traumi colpiscono di solito solo alcune dita.'),
  (119, 'problemi', 'Da cosa dipende spesso una rottura in zona 2?', '["Apex assente o mal posizionato","Troppo olio per cuticole a casa","Un colore scuro molto pigmentato","Un top troppo lucido e rigido"]'::jsonb, 0, 'La zona 2 è sopra il punto di stress: se lì manca lo spessore, la struttura non regge la leva e si rompe.'),
  (120, 'problemi', 'Che cosa favorisce il picco di calore in lampada?', '["Strati sottili","Strati spessi e lamina assottigliata","Un gel a basso calore","La modalità low heat della lampada"]'::jsonb, 1, 'La polimerizzazione è esotermica: più prodotto reagisce insieme, più calore si libera, e una lamina sottile lo lascia passare.'),
  (121, 'problemi', 'Perché un gel non abbinato alla lampada può scottare di più?', '["Perché la lampada si surriscalda","Perché il calore arriva tutto insieme","Perché il gel diventa più spesso","Perché la luce UV brucia la pelle"]'::jsonb, 1, 'Una lampada troppo potente per quel gel concentra la reazione in pochi secondi: lo stesso calore arriva tutto insieme ed è meno sopportabile.'),
  (122, 'problemi', 'A cosa serve la tecnica "flash and pull"?', '["Ad accelerare la polimerizzazione","A ridurre il calore percepito","A rimuovere il gel","A lucidare il top"]'::jsonb, 1, 'Si toglie la mano dalla lampada per qualche secondo e la si rimette: il calore si distribuisce nel tempo ed è più sopportabile.'),
  (123, 'problemi', 'Che cosa indicano di solito le grinze sul gel?', '["Strato spesso, indurito solo sopra","Troppo primer sotto la base","Una grana di lima sbagliata","Un top steso troppo sottile"]'::jsonb, 0, 'Sopra si forma una pelle dura su gel ancora molle: la soluzione sono strati sottili e tempi corretti.'),
  (124, 'problemi', 'Perché un colore scuro steso spesso fa le grinze?', '["Perché è scaduto o mal conservato","Perché i pigmenti fanno ombra","Perché il top è opaco e trattiene calore","Perché l''unghia è troppo corta"]'::jsonb, 1, 'I pigmenti fanno ombra e la luce non arriva negli strati sotto: solo la superficie indurisce e si raggrinzisce sul gel liquido. Servono strati sottili.'),
  (125, 'problemi', 'Un gel sottopolimerizzato aumenta soprattutto il rischio di…', '["Ingiallimento immediato","Allergia","Unghie troppo dure","Picchi di calore"]'::jsonb, 1, 'Il monomero non reagito resta libero e, a contatto con la pelle, la sensibilizza.'),
  (126, 'problemi', 'Una cliente ha prurito e rossore intorno alle unghie dopo il servizio. Cosa fai?', '["Aggiungi un altro strato di top","Rimuovi il prodotto e consigli il medico","Le dai una crema e lasci il prodotto","Aspetti il refill per valutare meglio"]'::jsonb, 1, 'Può essere una dermatite allergica da contatto: va valutata dal medico; annotala sulla scheda e rivedi la tecnica.'),
  (128, 'professione', 'Quale dato NON serve nella scheda cliente?', '["Allergie","Farmaci e patologie","Professione del coniuge","Consensi privacy"]'::jsonb, 2, 'La scheda raccoglie solo i dati utili alla sicurezza del servizio: il GDPR chiede di non raccogliere dati non necessari.'),
  (129, 'professione', 'Allergie, farmaci e gravidanza scritti nella scheda cliente sono…', '["Dati comuni, come nome e telefono","Dati relativi alla salute","Dati pubblici, se la cliente li dice","Dati fiscali, da conservare 10 anni"]'::jsonb, 1, 'Sono dati relativi alla salute, "categorie particolari" (art. 9 GDPR): servono informativa, consenso esplicito e custodia sicura.'),
  (130, 'professione', 'Per pubblicare sui social la foto delle mani di una cliente cosa serve?', '["Niente, se le unghie le hai fatte tu","Un consenso separato e specifico","La firma sulla scheda del servizio","Basta non mostrare il viso della cliente"]'::jsonb, 1, 'La foto non è necessaria al servizio: serve un consenso a parte, che la cliente può rifiutare e che, secondo la Cassazione, non si ricava dalla firma del contratto.'),
  (131, 'professione', 'Quale consiglio dai alla cliente dopo il trattamento?', '["Usare le unghie come attrezzo","Olio ogni giorno e guanti in casa","Togliere da sola il prodotto sollevato","Rimandare il refill finché regge"]'::jsonb, 1, 'Olio per cuticole ogni giorno e guanti per i lavori domestici proteggono pelle e prodotto da acqua e detergenti e allungano la durata del lavoro.'),
  (132, 'professione', 'Quale foto mostra meglio la posizione dell''apex?', '["Dall''alto","Di profilo","Dalla punta, a tunnel","Da sotto il bordo libero"]'::jsonb, 1, 'Di profilo si vedono apex e spessore; dall''alto forma e smile line, a tunnel la curva a C.'),
  (133, 'professione', 'Qual è il prezzo indicativo di un refill in Italia?', '["Circa 5–10 €","Circa 25–35 €","Circa 90–100 €","Circa 150 €"]'::jsonb, 1, 'È l''ordine di grandezza riportato da articoli e testimonianze 2021–2025; i prezzi variano molto per zona e tipo di centro.'),
  (134, 'professione', 'Come si calcola il costo dei materiali per servizio?', '["Prezzo di un vasetto diviso per dieci servizi","Spesa mensile in prodotti diviso le clienti del mese","Prezzo del servizio meno il tuo compenso orario","Spesa annuale in prodotti divisa per 12"]'::jsonb, 1, 'Così ottieni il costo medio reale per cliente; meglio fare la media su più mesi per tener conto dei periodi più o meno pieni.'),
  (135, 'professione', 'Nel regime forfettario, su cosa si calcolano imposta e contributi di un''estetista?', '["Su tutti gli incassi","Sul 67% degli incassi (coefficiente di redditività)","Solo sugli incassi in contanti","Sul guadagno dopo aver tolto le spese reali"]'::jsonb, 1, 'Le spese reali non si scaricano: sono comprese in modo forfettario nel 33% degli incassi che non viene tassato.'),
  (136, 'professione', 'Come funzionano i contributi INPS fissi degli artigiani?', '["Si pagano solo sopra 85.000 € di ricavi","Si pagano sul minimale anche se si guadagna meno","In forfettario non si pagano","Si pagano una volta sola, all''apertura"]'::jsonb, 1, 'Nel 2026 il minimale è 18.808 €: circa 4.521 € l''anno anche con redditi più bassi; in forfettario si può chiedere la riduzione del 35%.'),
  (137, 'professione', 'In gara, cosa valutano soprattutto i giudici?', '["Il prezzo del servizio","Struttura, simmetria e pulizia","La marca dei prodotti","La velocità di esecuzione"]'::jsonb, 1, 'Le schede punteggi premiano apex, curva a C, simmetria, smile line e pulizia del lavoro: sono questi criteri a decidere la classifica.'),
  (138, 'onicofagia', 'Quale situazione è una controindicazione alla ricostruzione su unghie rosicchiate?', '["Unghie cortissime con letto ungueale ridotto","Pus e gonfiore intorno all''unghia","Cuticole secche con pellicine","Lamina sottile e flessibile"]'::jsonb, 1, 'Pus e gonfiore indicano un''infezione o un''infiammazione in corso: non si lavora e si consiglia il medico. Le altre situazioni richiedono solo una tecnica adattata.'),
  (139, 'onicofagia', 'Perché, su un''unghia rosicchiata, chiudi la cartina tirandola leggermente verso il basso?', '["Per usare meno prodotto in zona 1 e alleggerire la punta","Per abbassare la pelle rialzata e fare spazio","Per accorciare il letto ungueale e nascondere il morso","Per inclinare l''allungamento verso l''alto e dare più curva"]'::jsonb, 1, 'Il cuscinetto di pelle rialzato occupa lo spazio dell''allungamento: tirando appena la cartina lo abbassi, senza schiacciarlo e senza provocare dolore.'),
  (140, 'onicofagia', 'Quale di queste è tra le cause più comuni della coilonichia (unghia a cucchiaio)?', '["La carenza di ferro","L''uso frequente della lima 180","Gli smalti di colore scuro","Il primer senza acido"]'::jsonb, 0, 'La carenza di ferro (anemia) è tra le cause più note e comuni, ma non l''unica: se la forma a cucchiaio è comparsa da poco, consiglia un controllo dal medico.'),
  (141, 'onicofagia', 'Con un''unghia ski-jump, cosa fai prima di applicare tip o cartina?', '["Allunghi di più per compensare la salita","Accorci l''unghia naturale fin dove la lamina è ancora dritta","Lucidi la lamina con il buffer","Posizioni la cartina seguendo la salita del bordo"]'::jsonb, 1, 'Se lasci la parte che sale, tip o cartina la seguono e l''allungamento punta in alto; accorciando appoggi l''allungamento su una lamina dritta.'),
  (142, 'onicofagia', 'Su un''unghia a pinza che fa male, cosa fa l''onicotecnica?', '["Accentua la curva a C con il pinching","Costruisce con più spessore sui lati","Consiglia il podologo o il medico","Usa una cartina più piatta e la preme"]'::jsonb, 2, 'La curva stretta comprime i tessuti e il dolore è un segnale: la cura spetta a podologo o medico. Su un''unghia a pinza niente pinching e niente forzature.'),
  (143, 'onicofagia', 'Su unghie molto grasse il gel si ritira dai bordi. Qual è la causa più probabile?', '["La lampada appena acquistata","Il sebo rimasto sulla lamina","Un colore troppo chiaro","La cartina di carta invece che di metallo"]'::jsonb, 1, 'Il sebo impedisce l''adesione: servono disidratante, un primer adatto e un nuovo sgrassaggio subito prima della base.'),
  (144, 'onicofagia', 'Secondo la regola usata dai formatori, quanto può essere lungo al massimo l''allungamento su un''unghia rosicchiata?', '["Il doppio del letto ungueale","Circa 1/3 della lunghezza della lamina","Quanto il letto ungueale","Quanto chiede la cliente, se l''apex è corretto"]'::jsonb, 1, 'Una leva lunga su una base piccola si stacca o si rompe: si parte corti, con circa 1/3 della lamina, e si allunga gradualmente ai refill successivi.'),
  (145, 'onicofagia', 'Perché si taglia una piccola "U" nella cartina su un''unghia rosicchiata?', '["Per far aderire meglio le alette sotto il polpastrello","Per non premere sul cuscinetto di pelle rialzato","Per disegnare la smile line","Per far scorrere il gel sotto il bordo"]'::jsonb, 1, 'Il cuscinetto davanti all''unghia è pelle viva: la piccola U fa appoggiare la cartina al bordo senza pressione e senza dolore.'),
  (146, 'onicofagia', 'Su un''unghia rosicchiata resta uno spazio tra lamina e cartina. Cosa succede?', '["Niente: il gel riempie lo spazio e rinforza la punta","Il prodotto cola sotto e crea uno scalino debole e \"mordibile\"","Il gel polimerizza più in fretta","La curva a C viene più regolare"]'::jsonb, 1, 'Il prodotto colato sotto il bordo forma uno scalino debole, che fa leva e offre un appiglio ai denti: la cartina deve stare a filo del bordo, anche se il bordo quasi non c''è.'),
  (147, 'onicofagia', 'Perché nelle prime settimane gli appuntamenti sono più ravvicinati?', '["Per abituare la cliente a venire spesso in salone","Perché all''inizio la tenuta è minore e va controllata","Perché il gel perde elasticità dopo due settimane","Perché la ricrescita è più veloce sulle unghie rosicchiate"]'::jsonb, 1, 'La superficie di appoggio è piccola e l''abitudine può ancora esserci: all''inizio servono controlli frequenti, poi si passa ai refill normali.'),
  (148, 'onicofagia', 'Un''unghia mostra una banda scura longitudinale comparsa da poco. Cosa fai?', '["La copri con un cover coprente","La limi leggermente per vedere se va via","Consigli una visita dal medico, senza fare ipotesi","Lavori normalmente e la ricontrolli al refill"]'::jsonb, 2, 'Una banda scura nuova va sempre valutata dal medico: non spetta all''onicotecnica dire da cosa dipende, e coprirla ritarderebbe il controllo.'),
  (149, 'onicofagia', 'Con un''unghia a cucchiaio, come si posiziona la cartina?', '["Seguendo la conca, così la cartina aderisce meglio","In asse con il dito, dopo aver livellato la conca","Inclinata verso l''alto, per assecondare la lamina","Senza cartina: sulle unghie a cucchiaio si usa solo il tip"]'::jsonb, 1, 'Seguendo la conca l''allungamento punterebbe in alto e il prodotto si accumulerebbe al centro: prima si livella la conca con un velo di builder, poi si allinea la cartina al dito.'),
  (150, 'cover-colori', 'A cosa serve principalmente il gel cover?', '["A dare la lucentezza finale e proteggere il colore","Ad allungare otticamente il letto e coprire imperfezioni","A sgrassare la lamina e migliorare l''adesione della base","A rendere più flessibile la zona cuticolare della ricostruzione"]'::jsonb, 1, 'È un gel costruttore pigmentato color pelle: prolunga visivamente il letto ungueale e uniforma le piccole discromie di una lamina sana.'),
  (151, 'cover-colori', 'Perché i gel molto pigmentati vanno stesi in strati sottili?', '["Per risparmiare prodotto senza perdere coprenza","Perché il pigmento ferma la luce prima del fondo","Per ottenere un effetto opaco senza top","Perché i gel pigmentati sono più fluidi e colano nei solchi"]'::jsonb, 1, 'Il pigmento fa da "ombrello" alla luce: in uno strato spesso la parte profonda resta sottopolimerizzata, morbida e più a rischio di allergia.'),
  (152, 'cover-colori', 'Il primo strato di un colore appare striato. Cosa significa di solito?', '["Che il prodotto è difettoso e va cambiato","È normale: il secondo strato uniforma","Che la lampada è da sostituire","Che lo strato va rimosso e rifatto più spesso"]'::jsonb, 1, 'Molti colori, soprattutto bianchi e pastello, coprono solo al secondo strato sottile: non serve ispessire il primo.'),
  (153, 'cover-colori', 'Quale di queste NON è una causa di ritiro del colore dai bordi?', '["Olio sulla lamina","Primer ancora umido sui lati","Lampada non compatibile con il gel","Colore steso in due strati sottili"]'::jsonb, 3, 'Olio, primer non asciutto e lampada non compatibile sono le cause tipiche del ritiro; due strati sottili sono invece la tecnica corretta.'),
  (154, 'cover-colori', 'Quale colore, sovrapposto in piccola quantità, attenua un tono giallastro?', '["Il viola (lilla)","Il verde","L''arancio","Il rosso"]'::jsonb, 0, 'Giallo e viola sono complementari, opposti sul cerchio cromatico: per questo i top "anti-giallo" hanno un velo lilla.'),
  (155, 'cover-colori', 'In un french con camouflage, in che ordine lavori?', '["Prima il bianco, poi il cover sopra","Prima il cover, poi la smile line sopra","Cover e bianco mescolati in un unico strato","Solo bianco, senza cover"]'::jsonb, 1, 'Il cover allunga otticamente il letto e la smile line si disegna appoggiandosi sopra, angoli compresi, così non restano zone trasparenti.'),
  (156, 'cover-colori', 'Perché, in un french su letto allungato, si abbassano leggermente gli angoli della smile line?', '["Per usare meno bianco","Per non lasciare zone trasparenti ai lati dove manca il cover","Per allungare il bordo libero","Per rendere la smile line più profonda al centro"]'::jsonb, 1, 'Se gli angoli restano troppo alti, tra bianco e cover si vedono due piccole "orecchie" trasparenti: abbassandoli il bianco tocca il cover.'),
  (157, 'cover-colori', 'Quali pigmenti assorbono più luce e sono più difficili da polimerizzare?', '["Bianco e blu","Rossi e neri","Solo i glitter","Nudi e rosa chiari"]'::jsonb, 1, 'Rossi e neri assorbono di più la luce: vanno stesi in strati sottili e polimerizzati con i tempi della scheda tecnica.'),
  (158, 'cover-colori', 'Uno strato di colore molto spesso si raggrinzisce dopo la lampada. Perché?', '["La lampada nuova è troppo potente per quel colore","Sopra indurisce, sotto resta morbido","Il colore è scaduto o mal conservato","Manca il top che lo tiene disteso"]'::jsonb, 1, 'La luce non arriva in fondo: sopra si forma una pelle dura su gel ancora molle. Un tempo più lungo non risolve, serve uno strato più sottile.'),
  (159, 'cover-colori', 'Come scegli il colore del cover con la cliente?', '["Sotto la lampada UV/LED, che mostra il colore polimerizzato","Alla luce naturale, con il campione sull''unghia","Sotto la luce calda del tavolo di lavoro","Sul catalogo del produttore, con le foto ufficiali"]'::jsonb, 1, 'La luce naturale mostra il colore com''è davvero; appoggiando il campione sull''unghia lo confronti direttamente con il letto ungueale.'),
  (160, 'cover-colori', 'Perché si "sigilla" il bordo libero passando il colore sullo spessore della punta?', '["Per decorare la punta","Per ridurre ritiro e scheggiature in punta","Per accorciare il tempo di lampada","Per rendere il colore più coprente"]'::jsonb, 1, 'Il colore avvolge il bordo e resta ancorato anche sullo spessore: si ritira meno e non si scheggia con l''uso.'),
  (161, 'cover-colori', 'Cosa consigliano i dermatologi americani sotto uno smalto rosso o arancio?', '["Nessuna base, per non ispessire lo smalto","Uno strato in più di base","Il top prima del colore, come barriera","Un passaggio di acetone sulla lamina prima del colore"]'::jsonb, 1, 'La base fa da barriera tra pigmento e lamina e previene l''ingiallimento; se la lamina si macchia, di solito torna normale in qualche settimana senza quel colore.'),
  (162, 'piedi', 'Rispetto alle mani, le unghie dei piedi crescono:', '["Più velocemente, perché sono più spesse","Alla stessa velocità di quelle delle mani","A meno della metà della velocità","Più lentamente solo d''inverno"]'::jsonb, 2, 'In uno studio su giovani adulti: circa 1,6 mm al mese per i piedi contro circa 3,5 mm per le mani, cioè meno della metà.'),
  (163, 'piedi', 'Per prevenire l''unghia incarnita, come si taglia l''unghia dell''alluce?', '["A punta, seguendo la forma del dito","Molto corta e tonda, per sicurezza","Dritta, angoli appena smussati","Scavando gli angoli laterali per liberarli"]'::jsonb, 2, 'È l''indicazione dei dermatologi (AAD): angoli tondi o scavati favoriscono l''ingresso dell''unghia nella pelle durante la crescita.'),
  (164, 'piedi', 'Un''unghia del piede è gialla, ispessita e friabile. Cosa fai?', '["La copri con un gel colorato coprente","La limi fino ad assottigliarla e poi la copri","Consigli medico o podologo","La ricostruisci in acrilico per proteggerla"]'::jsonb, 2, 'Sono segni compatibili con una micosi: è una controindicazione, non si copre e non si lima, e la diagnosi spetta a medico o podologo.'),
  (165, 'piedi', 'Chi tratta le unghie incarnite in Italia?', '["L''estetista","L''onicotecnica","Il podologo (o il medico)","L''estetista con un corso specifico"]'::jsonb, 2, 'Il podologo è una professione sanitaria (DM 666/1994): unghie incarnite, ipertrofiche e callosità sono di sua competenza, non dell''estetica.'),
  (166, 'piedi', 'Cliente diabetica con una ferita al piede che non guarisce. Cosa fai?', '["Pedicure con la lama, evitando la ferita","Pediluvio caldo per disinfettare","Nessun servizio e invio a medico o podologo","Solo semipermanente, senza pediluvio"]'::jsonb, 2, 'Nel diabete una ferita può non essere percepita e infettarsi facilmente: con ferite, ulcere o infezioni non si lavora.'),
  (167, 'piedi', 'Cosa esclude la L. 1/1990 dall''attività di estetista?', '["La manicure e la pedicure estetica","Le prestazioni terapeutiche","Il trucco del viso","Il massaggio estetico del corpo"]'::jsonb, 1, 'L''estetista lavora solo a scopo estetico: le prestazioni con finalità terapeutica, che curano una patologia, appartengono alle professioni sanitarie.'),
  (168, 'piedi', 'Dopo ogni cliente, cosa fai con la vaschetta del pediluvio?', '["La risciacqui con acqua calda e la asciughi","Pulizia, disinfezione con tempo di contatto, asciugatura e registro","La spruzzi di disinfettante e la riempi subito","La disinfetti una volta sola a fine giornata e registri"]'::jsonb, 1, 'Senza pulizia con sapone il disinfettante funziona male, e senza il tempo di contatto indicato in etichetta non agisce; il registro documenta ogni disinfezione.'),
  (169, 'piedi', 'Che consiglio dai alla cliente prima di una pedicure?', '["Radersi le gambe la mattina stessa","Non radersi le gambe nelle 24 ore prima","Mettere crema grassa sui piedi","Ammorbidire i piedi con un pediluvio caldo a casa"]'::jsonb, 1, 'I microtagli del rasoio sono porte d''ingresso per i germi: in uno studio chi si era rasato aveva più del doppio di probabilità di infezione.'),
  (170, 'piedi', 'Quanto tempo può servire perché un''unghia dell''alluce si rinnovi del tutto?', '["Circa 2 settimane","Circa 1 mese","Fino a 12–18 mesi","Circa 3–4 mesi, come le mani"]'::jsonb, 2, 'Le unghie dei piedi crescono circa 1,6 mm al mese e l''alluce è il più lento: il ricambio completo richiede 12–18 mesi.'),
  (171, 'piedi', 'Con una cliente diabetica, come controlli la temperatura dell''acqua?', '["Chiedendo alla cliente se va bene","Con il termometro o con il tuo gomito","Facendo immergere prima un piede alla cliente","Non serve, basta acqua del rubinetto"]'::jsonb, 1, 'Con la neuropatia la cliente può non sentire il calore e scottarsi: la temperatura (acqua tiepida) la verifichi tu.'),
  (172, 'piedi', 'Secondo il DM 666/1994, chi tratta le callosità del piede?', '["L''estetista con la lama","Il podologo","L''onicotecnica","Chiunque abbia un attestato di pedicure"]'::jsonb, 1, 'Il podologo tratta con metodi incruenti callosità, unghie ipertrofiche, deformi e incarnite; rimuovere un callo con la lama non è un lavoro estetico.'),
  (173, 'piedi', 'Perché i pediluvi con tubature di ricircolo sono considerati più a rischio?', '["Consumano molta più acqua e prodotto","Nelle tubature crescono micobatteri difficili da eliminare","Scaldano troppo l''acqua per chi ha il diabete","Gli idromassaggi irritano la pelle secca dei piedi"]'::jsonb, 1, 'In un''indagine dei CDC in California sono stati trovati micobatteri in 29 vasche su 30: per questo oggi si preferiscono vaschette senza tubature.'),
  (174, 'arte-gare', 'Su cosa si applica la polvere chrome?', '["Su gel colorato non polimerizzato","Su top no-wipe polimerizzato","Sulla base ancora appiccicosa","Sulla lamina nuda"]'::jsonb, 1, 'La polvere si strofina sul top no-wipe appena polimerizzato, che è liscio e senza strato di dispersione; poi si sigillano i bordi e si mette il top.'),
  (175, 'arte-gare', 'Nel cat-eye, quando si usa il magnete?', '["Dopo il top","Prima di polimerizzare lo strato magnetico","Dopo la polimerizzazione completa","Prima di stendere il gel magnetico"]'::jsonb, 1, 'Le particelle metalliche si orientano solo finché il gel è fluido: una volta polimerizzato il disegno non cambia più.'),
  (176, 'arte-gare', 'Nel one-stroke, come si carica il pennello piatto per iniziare?', '["Con un solo colore su tutta la larghezza","Con due colori, uno per lato, circa metà e metà","Fino alla ghiera, per avere più colore","Asciutto, intinto solo sulla punta"]'::jsonb, 1, 'Ogni lato porta un colore, così una sola pennellata crea luce e ombra; il colore non deve entrare nella ghiera.'),
  (177, 'arte-gare', 'In gara, cosa comporta il gel non polimerizzato a fine prova?', '["−5 punti","Nessuna penalità","La squalifica","Punti in meno solo nella pulizia"]'::jsonb, 2, 'Nei regolamenti Nailympia il gel non polimerizzato a fine gara porta alla squalifica, come pulire le unghie dopo lo stop.'),
  (178, 'arte-gare', 'Che cosa valuta soprattutto la "vista a tunnel"?', '["La smile line","La curva a C","Il colore","La lucentezza"]'::jsonb, 1, 'Si guarda l''unghia dalla punta, come dentro un tunnel: si vede se la curva a C è regolare, simmetrica e uguale sulle dita.'),
  (179, 'arte-gare', 'In un''unghia con decorazione incapsulata, come si gestisce l''apex?', '["Non serve: la decorazione fa già da struttura","Si costruisce sopra la decorazione","Si sposta verso la cuticola per non coprirla","Si sostituisce con uno strato di glitter incapsulato"]'::jsonb, 1, 'La decorazione non cambia le regole della struttura: l''apex resta sopra il punto di stress e la copre.'),
  (180, 'arte-gare', 'Prima del top finale sul chrome, perché si passa un buffer leggero sul bordo libero?', '["Per accorciare l''unghia prima del top","Per togliere la polvere libera","Per opacizzare il chrome e attenuare il riflesso","Per arrotondare gli angoli e non farli impigliare"]'::jsonb, 1, 'La polvere rimasta sulla punta fa da strato separatore e impedisce al top di aderire: va tolta prima di sigillare.'),
  (181, 'arte-gare', 'Il gel per foil "non tiene" il foil. Qual è la causa probabile?', '["Strato spesso o poco polimerizzato","Lampada troppo nuova e potente","Foil troppo lucido o di bassa qualità","Colore sotto troppo chiaro per il foil"]'::jsonb, 0, 'Il foil si trasferisce su un velo sottile di gel polimerizzato che resta appiccicoso: uno strato spesso o poco polimerizzato non lo trattiene.'),
  (182, 'arte-gare', 'Dove conviene incapsulare una decorazione?', '["Vicino alla cuticola, dove si vede di più","Sui lati, vicino ai solchi, per non disturbare","Nelle zone spesse, come smile line e apex","Sul bordo libero, dove lo spessore è minimo"]'::jsonb, 2, 'Nelle zone spesse (smile line, apex, centro della punta) c''è spazio per coprirla; nelle zone sottili resterebbe un rigonfiamento oppure la limeresti via.'),
  (183, 'arte-gare', 'In una gara Nailympia, cosa succede se pulisci le unghie della modella dopo lo stop?', '["Nulla, se non le tocchi con la lima","−5 punti","La squalifica","Punti in meno solo nella zona cuticolare"]'::jsonb, 2, 'Pulire mani o unghie con qualsiasi prodotto dopo lo stop, anche con aria compressa, porta alla squalifica.'),
  (184, 'arte-gare', 'Nella scheda Nailympia 2026 French Twist 3-Shape Challenge, quanto vale l''apex?', '["30 punti, con un giudice dedicato solo all''apex","15 punti, insieme alla curva a C","5 punti, come criterio secondario","Non è un criterio a sé: rientra nella forma"]'::jsonb, 1, 'Il giudice 3 valuta curva a C e apex: 15 punti ciascuno, 30 in tutto per i due criteri.'),
  (185, 'arte-gare', 'Perché il gel cat-eye si "flasha" pochi secondi subito dopo il magnete?', '["Per non far seccare il gel nel pennello","Perché le particelle si spostano ancora","Perché il magnete perde forza dopo pochi secondi","Per evitare di dover mettere il top finale"]'::jsonb, 1, 'Finché il gel è fluido le particelle continuano a muoversi e il disegno si perde: un flash breve, un dito alla volta, le fissa nella posizione voluta.')
